def parse_scm(collection, version):
    if ',' in collection:
        collection, version = collection.split(',', 1)
    elif version == '*' or not version:
        version = 'HEAD'

    if collection.startswith('git+'):
        path = collection[4:]
    else:
        path = collection

    path, fragment = urldefrag(path)
    fragment = fragment.strip(os.path.sep)

    if path.endswith(os.path.sep + '.git'):
        name = path.split(os.path.sep)[-2]
    elif '://' not in path and '@' not in path:
        name = path
    else:
        name = path.split('/')[-1]
        if name.endswith('.git'):
            name = name[:-4]

    return name, version, path, fragment


def _download_file(url, b_path, expected_hash, validate_certs, headers=None):
    urlsplit = os.path.splitext(to_text(url.rsplit('/', 1)[1]))
    b_file_name = to_bytes(urlsplit[0], errors='surrogate_or_strict')
    b_file_ext = to_bytes(urlsplit[1], errors='surrogate_or_strict')
    b_file_path = tempfile.NamedTemporaryFile(dir=b_path, prefix=b_file_name, suffix=b_file_ext, delete=False).name

    display.vvv("Downloading %s to %s" % (url, to_text(b_path)))
    # Galaxy redirs downloads to S3 which reject the request if an Authorization header is attached so don't redir that
    resp = open_url(to_native(url, errors='surrogate_or_strict'), validate_certs=validate_certs, headers=headers,
                    unredirected_headers=['Authorization'], http_agent=user_agent())

    with open(b_file_path, 'wb') as download_file:
        actual_hash = _consume_file(resp, download_file)

    if expected_hash:
        display.vvvv("Validating downloaded file hash %s with expected hash %s" % (actual_hash, expected_hash))
        if expected_hash != actual_hash:
            raise AnsibleError("Mismatch artifact hash with downloaded file")

    return b_file_path


def _extract_tar_file(tar, filename, b_dest, b_temp_path, expected_hash=None):
    b_dest_filepath = _tar_destination(filename, b_dest)
    with _get_tar_file_member(tar, filename) as (tar_member, tar_obj):
        if not (tar_member.isfile() or tar_member.issym()) or tar_obj is None:
            raise AnsibleError("Cannot extract tar entry '%s' as a file" % to_native(filename))

        b_linkname = to_bytes(tar_member.linkname, errors='surrogate_or_strict')
        preserve_link = tar_member.issym() and _is_child_path(b_linkname, b_dest, b_dest_filepath)
        b_tmp_name = None
        try:
            with tempfile.NamedTemporaryFile(dir=b_temp_path, delete=False) as tmpfile_obj:
                b_tmp_name = to_bytes(tmpfile_obj.name, errors='surrogate_or_strict')
                actual_hash = _consume_file(tar_obj, tmpfile_obj)

            if expected_hash and actual_hash != expected_hash:
                raise AnsibleError("Checksum mismatch for '%s' inside collection at '%s'"
                                   % (to_native(filename, errors='surrogate_or_strict'), to_native(tar.name)))

            b_parent_dir = os.path.dirname(b_dest_filepath)
            if not os.path.exists(b_parent_dir):
                os.makedirs(b_parent_dir, mode=0o0755)
            if not _is_child_path(b_parent_dir, b_dest):
                raise AnsibleError("Cannot extract tar entry '%s' as it will be placed outside the collection directory"
                                   % to_native(filename, errors='surrogate_or_strict'))

            if preserve_link:
                os.symlink(b_linkname, b_dest_filepath)
            else:
                shutil.move(b_tmp_name, b_dest_filepath)
                b_tmp_name = None
                new_mode = 0o644
                if stat.S_IMODE(tar_member.mode) & stat.S_IXUSR:
                    new_mode |= 0o0111
                os.chmod(b_dest_filepath, new_mode)
        finally:
            if b_tmp_name is not None and os.path.exists(b_tmp_name):
                os.unlink(b_tmp_name)


def _tar_destination(filename, b_dest):
    b_dest = os.path.abspath(b_dest)
    b_filepath = os.path.abspath(os.path.join(b_dest, to_bytes(filename, errors='surrogate_or_strict')))
    if b_filepath == b_dest or not b_filepath.startswith(b_dest + to_bytes(os.path.sep)):
        raise AnsibleError("Cannot extract tar entry '%s' as it will be placed outside the collection directory"
                           % to_native(filename, errors='surrogate_or_strict'))
    return b_filepath


def _extract_tar_dir(tar, filename, b_dest):
    b_dest_filepath = _tar_destination(filename, b_dest)
    tar_member = tar.getmember(to_native(filename, errors='surrogate_or_strict'))
    b_parent_dir = os.path.dirname(b_dest_filepath)
    if not os.path.exists(b_parent_dir):
        os.makedirs(b_parent_dir, mode=0o0755)
    if not _is_child_path(b_parent_dir, b_dest):
        raise AnsibleError("Cannot extract tar entry '%s' as it will be placed outside the collection directory"
                           % to_native(filename, errors='surrogate_or_strict'))
    if tar_member.issym() and _is_child_path(to_bytes(tar_member.linkname, errors='surrogate_or_strict'),
                                             b_dest, b_dest_filepath):
        os.symlink(to_bytes(tar_member.linkname, errors='surrogate_or_strict'), b_dest_filepath)
    elif tar_member.isdir() or tar_member.issym():
        os.makedirs(b_dest_filepath, mode=0o0755)
    else:
        raise AnsibleError("Cannot extract tar entry '%s' as a directory" % to_native(filename))


def _get_tar_file_member(tar, filename):
    n_filename = to_native(filename, errors='surrogate_or_strict')
    try:
        member = tar.getmember(n_filename)
    except KeyError:
        raise AnsibleError("Collection tar at '%s' does not contain the expected file '%s'." % (
            to_native(tar.name),
            n_filename))

    return _tarfile_extract(tar, member)


